def create_svg_icon(icon_name, extra_classes=''):
    """Create SVG icon from Font Awesome icon name"""
    # Remove 'fa-' prefix
    icon_key = icon_name.replace('fa-', '')
    
    if icon_key in ICON_MAP:
        svg_path = ICON_MAP[icon_key]
        return f'<svg class="svg-icon {extra_classes}" viewBox="0 0 16 16" fill="currentColor" width="16" height="16">{svg_path}</svg>'
    
    return f'<!-- Icon {icon_name} not found -->'

def process_file(filepath):
    """Process a single HTML file"""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
        
        original = content
        
        # Find all <i class="fas fa-XXX"></i> patterns
        pattern = r'<i\s+class="([^"]*fa-[^"]*)"[^>]*></i>'
        
        def replace_icon(match):
            classes = match.group(1)
            # Extract just the fa- classes
            fa_classes = [c for c in classes.split() if c.startswith('fa-')]
            
            if not fa_classes:
                return match.group(0)
            
            # Create SVG for each fa- class
            svg_icons = []
            for fa_class in fa_classes:
                svg_icons.append(create_svg_icon(fa_class))
            
            return ''.join(svg_icons)
        
        content = re.sub(pattern, replace_icon, content)
        
        if content != original:
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(content)
            print(f"✓ Updated: {filepath}")
            return True
        
        return False
        
    except Exception as e:
        print(f"✗ Error with {filepath}: {e}")
        return False

def main():
    """Main function to process all HTML files"""
    templates_dir = '/Users/wuchenghao/Library/CloudStorage/OneDrive-个人/文档/MTSCOS_AI_Project/flask-app/app/templates'
    
    count = 0
    for root, dirs, files in os.walk(templates_dir):
        for file in files:
            if file.endswith('.html'):
                filepath = os.path.join(root, file)
                if process_file(filepath):
                    count += 1
    
    print(f"\n✅ Complete! Updated {count} files.")
    print("\nAll Font Awesome <i> tags have been replaced with inline SVG icons!")

if __name__ == '__main__':
    main()
